'use strict';

const {
  exec
} = require('child_process');
function bitrixUpdateInternals() {
  exec('npx update-browserslist-db@latest', (err, stdout, stderr) => {
    if (err) {
      console.error(err);
    } else {
      console.log(stdout);
      console.error(stderr);
    }
  });
}

module.exports = bitrixUpdateInternals;
